-- 00068_tender_packs_bucket.sql
--
-- Strategic Trio #2 — One-click Tender Pack export. A private storage bucket
-- for the branded compliance-evidence PDFs generated by the
-- generate-tender-pack edge function. Mirrors the statements-of-compliance
-- bucket (00061): private, no public RLS policies — the edge function reads/
-- writes with the service role and hands clients short-lived signed URLs only.

insert into storage.buckets (id, name, public)
values ('tender-packs', 'tender-packs', false)
on conflict (id) do nothing;
